// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(153000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();

    const pagedResponsePromise = page.waitForResponse(
        (response) => response.url().includes('/petclinic/api/v2/owners')
    );
    await page.getByRole("link", { name: "Search" }).click();
    const pagedResponse = await pagedResponsePromise;

    expect(pagedResponse.status()).toBe(200);
    const ownersPage = await pagedResponse.json();
    expect(ownersPage.page).toBe(0);
    expect(ownersPage.content.length).toBe(ownersPage.size);
    await expect(page.locator('#ownersTable .ownerFullName')).toHaveCount(ownersPage.content.length);

    const unpagedResponsePromise = page.waitForResponse(
        (response) => new URL(response.url()).pathname.endsWith('/petclinic/api/owners')
    );
    await page.getByRole("button", { name: "Find Owner" }).click();
    const unpagedResponse = await unpagedResponsePromise;

    expect(unpagedResponse.status()).toBe(200);
    const allOwners = await unpagedResponse.json();
    expect(allOwners.length).toBe(ownersPage.totalElements);
    expect(allOwners[0].firstName).toBe("George");
    expect(allOwners[0].lastName).toBe("Franklin");
    expect(allOwners[ownersPage.totalElements]).toBeUndefined();
    await expect(page.locator('#ownersTable .ownerFullName')).toHaveCount(ownersPage.totalElements);
    await expect(page.getByRole('link', { name: 'Carlos Estaban' })).toBeVisible();
});
